import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"CAF/WAF Assessment Platform","description":"Run a read-only CAF/WAF assessment with AzureScout — architecture, every run mode, the assessment registry, and minimum auth per scan type.","frontmatter":{"description":"Run a read-only CAF/WAF assessment with AzureScout — architecture, every run mode, the assessment registry, and minimum auth per scan type."},"headers":[],"relativePath":"assessment/assessment.md","filePath":"assessment/assessment.md"}'),i={name:"assessment/assessment.md"};function o(r,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="caf-waf-assessment-platform" tabindex="-1">CAF/WAF Assessment Platform <a class="header-anchor" href="#caf-waf-assessment-platform" aria-label="Permalink to &quot;CAF/WAF Assessment Platform&quot;">​</a></h1><p>Introduced in <strong>v2.0.0</strong>, AzureScout can score a tenant against the Microsoft <strong>Cloud Adoption Framework (CAF)</strong> design areas and <strong>Well-Architected Framework (WAF)</strong> pillars — not just inventory it. The assessment is <strong>read-only</strong> end to end (ARM Reader at the management-group root, plus read-only Graph app permissions for a subset of scans — see <a href="./assessment-permissions.html">Auth &amp; permissions per scan type</a>).</p><div class="info custom-block"><p class="custom-block-title">Inventory and assessment are different questions</p><p><strong>Inventory</strong> answers <em>&quot;what is there?&quot;</em> — a list of resources and their properties, no opinion attached. <strong>Assessment</strong> answers <em>&quot;is what is there any good?&quot;</em> — findings, a Pass/Fail/Partial verdict per rule, and a score, measured against CAF/WAF. Assessment always <em>consumes</em> inventory (you cannot score what has not been discovered); inventory stands alone and needs no assessment to be useful. This page is about assessment. For the resources themselves, run <code>Invoke-AzureScout</code> without <code>-Assessment</code> — see <a href="./../guide/overview.html">Overview</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">PowerShell 7 required</p><p><strong>PowerShell 7 on PowerShell Core</strong> — for the whole module, not just this mode. <code>AzureScout.psd1</code> declares <code>PowerShellVersion = &#39;7.0&#39;</code> and <code>CompatiblePSEditions = @(&#39;Core&#39;)</code>, so <code>Import-Module</code> rejects Windows PowerShell 5.1 outright. The manifest declares the core inventory and assessment modules; assessment mode may additionally need a <code>.NET SDK</code> for the PowerPoint tier — see <a href="./assessment-prerequisites.html">Assessment Prerequisites</a>. The PowerPoint tier is currently on hold, so the <code>.NET SDK</code> is not needed for a run today.</p></div><div class="info custom-block"><p class="custom-block-title">One command</p><p>Assessment is a mode of <code>Invoke-AzureScout</code>, not a separate tool: <code>Invoke-AzureScout -Assessment &#39;CAF: Azure Landing Zone&#39;</code>. The former standalone assessment command was removed in v3.0.0; use the unified entry point — see <a href="./../guide/overview.html">Overview</a>.</p></div><h2 id="architecture-—-three-layers-json-on-disk" tabindex="-1">Architecture — three layers, JSON on disk <a class="header-anchor" href="#architecture-—-three-layers-json-on-disk" aria-label="Permalink to &quot;Architecture — three layers, JSON on disk&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>COLLECT  --collect.json--&gt;  ASSESS  --findings.json--&gt;  REPORT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Each layer runs independently from its JSON input, so you can collect once and assess later, or re-render reports from an existing findings set without re-scanning.</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Collect</strong></td><td>Read-only Azure Resource Graph queries produce a normalized <code>collect.json</code>, including a per-domain <code>domains.*</code> namespace.</td></tr><tr><td><strong>Ingest</strong></td><td>Folds governance data (natively collected by default — see below) and Azure Advisor into the same <code>collect.json</code>.</td></tr><tr><td><strong>Assess</strong></td><td>A declarative rule engine grades the collected data — <strong>395 rules across 44 rule files</strong> (170 evaluated automatically, 225 requiring manual confirmation) — producing scored <code>findings.json</code> with a prioritized gap list.</td></tr><tr><td><strong>Report</strong></td><td>Renders <code>findings.json</code> into tiered deliverables.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Governance data is collected natively — no AzGovViz dependency</p><p><code>Import-Governance</code> (<code>src/ingest/Import-Governance.ps1</code>) is the <strong>default</strong> governance collector for the 26 assessments that need governance data (<code>CAF: Azure Landing Zone</code>, <code>Management</code>, <code>Identity</code>, <code>Scout: Governance Baseline</code>, <code>Policy</code> — their manifest <code>Ingest</code> value is <code>Governance</code>, not <code>AzGovViz</code>). It populates <code>collect.json</code>&#39;s <code>governance</code> object natively from Azure Resource Graph (policy assignments, role assignments, management groups) plus ambient-token ARM REST calls (budgets, resource locks) — no cloned repo, no <code>AzAPICall</code> install prompt, fully unattended. It needs only <strong>ARM Reader at the management-group root</strong>, same as every other assessment — no additional Graph permission.</p><p>Since AB#6779, four of those five datasets are collected once by the collection pass (<code>src/collect/Get-ScoutGovernanceDataset.ps1</code>) rather than here: role assignments, policy assignments, resource locks and budgets. That is what lets the inventory report render them as worksheets — <code>Role Assignments</code>, <code>Policy Assignments</code>, <code>Resource Locks</code> and <code>Budgets</code> — without a second round trip. <code>Import-Governance</code> reuses whatever the collect pass hands it and queries only what it is not given, so the call count for an assessment run is unchanged. Management groups are still collected here.</p><p>The third-party Azure Governance Visualizer remains available as an <strong>opt-in</strong><code>Ingest</code> value if you want it specifically, but nothing depends on it by default anymore. Live-verified against the HCS tenant: real policy/role assignments are collected, CAF governance/identity rules score real Pass/Fail, and the ALZ benchmark degrades to an explicit <code>Unknown</code> — not a false 0% — when management-group data isn&#39;t visible to the identity running the scan. Two datasets are intentionally always empty: <code>classicAdministrators</code> (a retired API — the CAF-IDN-03 rule asserts <code>notExists</code>, so empty is compliant) and <code>pimEligibility</code> (needs an Entra ID P2 license plus <code>PrivilegedAccess.Read.AzureResources</code>, which only the opt-in AzGovViz path ever requests).</p></div><div class="info custom-block"><p class="custom-block-title"><code>ArgQueryPack</code> is retired</p><p>The <code>ArgQueryPack</code> ingestor is gone. It re-ran six Resource Graph queries that <code>Invoke-Collect</code> had already gathered, and it <strong>overwrote</strong> the collector&#39;s results with worse copies — two of its six queries had no divide-by-zero guard where the collector&#39;s had one, and a <code>-Force</code> replace from this ingestor had already caused a live incident (a false <code>CAF-SEC-03</code>/<code>CAF-SEC-06</code> fail from wiped networking data). If a manifest entry still names <code>ArgQueryPack</code> in its <code>Ingest</code> list, it is now silently ignored (with a verbose message) rather than run — no assessment depended on data that <code>ArgQueryPack</code> alone provided.</p></div><div class="info custom-block"><p class="custom-block-title">Collect is now actually scoped by category</p><p><code>Invoke-Collect.ps1</code>&#39;s <code>-Categories</code> parameter (populated from each assessment&#39;s declared <code>Collect</code> list, or your <code>-Category</code> override) <strong>does filter which Resource Graph queries run</strong>. Every query in <code>Invoke-Collect</code> is tagged with the <code>Collect</code> category name(s) whose rule files reference its output — cross-domain references included (e.g. <code>waf.security</code> needs <code>domains.databases.sqlServers</code>, so that query runs for both <code>Databases</code> and <code>Security</code>). <code>subscriptions</code> always runs (base data every rule set needs). Passing <code>-Categories &#39;*&#39;</code> (or an empty list, or omitting <code>-Category</code>/leaving an assessment&#39;s own <code>Collect</code> list at <code>@(&#39;*&#39;)</code> — <code>CAF: Azure Landing Zone</code> and <code>Estate</code> both do this) runs every query, same as before. The practical effect: <code>-Assessment &#39;Assess: Security&#39;</code> now collects a materially smaller set of resource types than <code>-Assessment &#39;CAF: Azure Landing Zone&#39;</code> (see the run below) — this is a different mechanism from <code>Invoke-AzureScout</code>&#39;s module-loading-level <a href="./../guide/category-filtering.html">Category Filtering</a>, but for the assessment platform it now actually shrinks scan time and query volume, not just what gets scored.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pulls only Security-relevant resource types (Key Vaults, NSGs, private</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># endpoints/DNS zones, SQL servers, ...) instead of the full ~25-query set.</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Assess: Security&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat Json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></div><h2 id="run-modes" tabindex="-1">Run modes <a class="header-anchor" href="#run-modes" aria-label="Permalink to &quot;Run modes&quot;">​</a></h2><p>Every discovery category is an independently runnable, tagged assessment — pass one, several, or <code>All</code> to <code>-Assessment</code>. All examples assume you&#39;ve installed and imported the module:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install once, from the PowerShell Gallery</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Install-Module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name AzureScout </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AllowClobber</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or import from a local clone</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Import-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AzureScout.psd1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="full-landing-zone-assessment" tabindex="-1">Full landing-zone assessment <a class="header-anchor" href="#full-landing-zone-assessment" aria-label="Permalink to &quot;Full landing-zone assessment&quot;">​</a></h3><p>Scores all 8 CAF areas and all 5 WAF pillars in one run, against an ALZ benchmark diff.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat All</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="single-category" tabindex="-1">Single category <a class="header-anchor" href="#single-category" aria-label="Permalink to &quot;Single category&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Assess: Security&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat React</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="multiple-assessments-in-one-run" tabindex="-1">Multiple assessments in one run <a class="header-anchor" href="#multiple-assessments-in-one-run" aria-label="Permalink to &quot;Multiple assessments in one run&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Assess: Networking&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Assess: Security&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat React</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Findings from both are combined into one <code>findings.json</code> and one set of reports for the run.</p><h3 id="every-assessment-all" tabindex="-1">Every assessment (<code>All</code>) <a class="header-anchor" href="#every-assessment-all" aria-label="Permalink to &quot;Every assessment (`All`)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment All </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat All</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-Assessment All</code> expands to every key in <code>manifests/assessments.psd1</code> — currently <strong>46 registry entries</strong> (see the generated <a href="./../reference/assessment-catalogue.html">Assessment Catalogue</a>). Most are not distinct assessments — see <a href="#all-24-registry-entries-and-what-the-wizard-actually-offers">the registry entries section below</a> and the <a href="./../design/assessment-registry.html">full registry</a> for what that number actually breaks down into.</p><h3 id="inventory-assessment-in-one-collect-inventoryandassessment-both" tabindex="-1">Inventory + assessment in one collect (<code>-InventoryAndAssessment</code> / <code>-Both</code>) <a class="header-anchor" href="#inventory-assessment-in-one-collect-inventoryandassessment-both" aria-label="Permalink to &quot;Inventory + assessment in one collect (`-InventoryAndAssessment` / `-Both`)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InventoryAndAssessment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat All</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Runs the full inventory pass and the assessment from <strong>one</strong> Azure collection — the assessment is handed the inventory&#39;s already-collected rows instead of re-querying. Previously this collect-once path was reachable only by answering &quot;both&quot; in the interactive wizard; <code>-InventoryAndAssessment</code> (alias <code>-Both</code>) reaches it from a script or CI without going through the wizard at all.</p><h3 id="unattended-one-command-run-invoke-scoutpipeline" tabindex="-1">Unattended, one-command run (<code>Invoke-ScoutPipeline</code>) <a class="header-anchor" href="#unattended-one-command-run-invoke-scoutpipeline" aria-label="Permalink to &quot;Unattended, one-command run (`Invoke-ScoutPipeline`)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-ScoutPipeline</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat All </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputPath </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D:\\Reports\\Scout&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>Invoke-ScoutPipeline</code> (exported public cmdlet, <code>src/Invoke-ScoutPipeline.ps1</code>) runs collect → assess → report <strong>headless</strong> in one call, writing everything into a single dated run folder. It is non-interactive throughout — it forces <code>$ConfirmPreference = &#39;None&#39;</code> and <code>$ProgressPreference = &#39;SilentlyContinue&#39;</code> for the duration of the run. By default it runs the read-only permission pre-flight first (pass <code>-SkipPermissionAudit</code> to skip it), and it wraps the orchestrator in try/catch so a failure in one exporter degrades the run to <code>PartialSuccess</code> rather than losing the output that did succeed.</p><p>It writes two summary files into the run folder alongside the usual report tiers:</p><ul><li><code>pipeline-summary.json</code> — CI-facing: <code>schemaVersion</code>, <code>startedOn</code> / <code>finishedOn</code>, <code>elapsedSeconds</code>, <code>assessments</code>, <code>formats</code>, <code>findingsByStatus</code>, <code>permissionAudit</code>, and <code>outcome</code> (one of <code>Success</code>, <code>PartialSuccess</code>, <code>Failed</code>).</li><li><code>pipeline-summary.md</code> — the human-readable equivalent.</li></ul><p><code>Invoke-ScoutPipeline</code> returns the run-folder path. It only throws (and sets <code>$LASTEXITCODE = 1</code>) when <code>outcome</code> is <code>Failed</code> — a <code>PartialSuccess</code> outcome returns normally so a CI step can inspect <code>pipeline-summary.json</code> and decide what to do with a partial run.</p><p>Parameters: <code>-Assessment</code>, <code>-OutputFormat</code> (default <code>All</code>), <code>-OutputPath</code>, <code>-ManagementGroupId</code>, <code>-Category</code>, <code>-SkipPermissionAudit</code> — the same run-mode semantics described throughout this page apply here too.</p><h3 id="collect-once-assess-later-collectonly-fromcollect" tabindex="-1">Collect once, assess later (<code>-CollectOnly</code> / <code>-FromCollect</code>) <a class="header-anchor" href="#collect-once-assess-later-collectonly-fromcollect" aria-label="Permalink to &quot;Collect once, assess later (`-CollectOnly` / `-FromCollect`)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop after Collect — writes collect.json and returns its path</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CollectOnly</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Re-run Assess + Report from that saved collect.json, no re-scan</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FromCollect .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20260720_101500</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">collect.json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat React</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JsonEvidence</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Useful for iterating on rule changes or re-rendering a different output tier without re-querying Azure.</p><h3 id="permission-pre-flight-permissionaudit" tabindex="-1">Permission pre-flight (<code>-PermissionAudit</code>) <a class="header-anchor" href="#permission-pre-flight-permissionaudit" aria-label="Permalink to &quot;Permission pre-flight (`-PermissionAudit`)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Assess: Identity&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermissionAudit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Checks read-only access for the requested assessment(s) <strong>before</strong> any collection runs — see <a href="./assessment-permissions.html">Auth &amp; permissions per scan type</a> for exactly what this does and does not verify.</p><h3 id="scoping-to-a-management-group-managementgroupid" tabindex="-1">Scoping to a management group (<code>-ManagementGroupId</code>) <a class="header-anchor" href="#scoping-to-a-management-group-managementgroupid" aria-label="Permalink to &quot;Scoping to a management group (`-ManagementGroupId`)&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ManagementGroup </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contoso-root-mg&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat React</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">Scopes Collect too now — and the benchmark still needs MG-root visibility</p><p><code>-ManagementGroupId</code> is passed to <code>Invoke-Collect</code>, which pass it through as <code>Search-AzGraph -ManagementGroup</code> on every Resource Graph query (and, if you&#39;ve opted into the legacy <code>AzGovViz</code> ingestor, to <code>Import-AzGovViz</code> too). Omit it and Collect keeps tenant-wide behavior (no <code>-ManagementGroup</code> filter is passed to <code>Search-AzGraph</code> at all — not an empty/wildcard scope, the parameter is left off entirely).</p><p>For the <strong>26 assessments that ingest governance data</strong> — every one marked <strong>Gov</strong> in the <a href="./../reference/assessment-catalogue.html">Assessment Catalogue</a>, including <code>CAF: Azure Landing Zone</code>, every <code>CAF:</code> design area and every <code>WAF:</code> pillar — the <strong>native</strong><code>Import-Governance</code> collector (the default <code>Ingest = Governance</code>) runs regardless of whether <code>-ManagementGroupId</code> is supplied — it does not silently skip. What actually needs management-group visibility is the <strong>ALZ benchmark diff</strong>: if the identity running the scan doesn&#39;t have Reader at the management-group root (with or without <code>-ManagementGroupId</code> set), the benchmark degrades to an explicit <code>Unknown</code> — not a false 0% — rather than failing loudly. See <a href="./assessment-permissions.html#-managementgroupid-and-governance-data-collection">Auth &amp; permissions per scan type</a>.</p></div><h3 id="scope" tabindex="-1"><code>-Scope</code> <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;`-Scope`&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope All        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># default</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope ArmOnly    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># identical to All today</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope EntraOnly  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># throws -- see below</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="info custom-block"><p class="custom-block-title">EntraOnly throws instead of silently collecting nothing</p><p>The assessment platform&#39;s Collect layer is ARG/ARM only — there is no Graph-based collection path in <code>Invoke-Collect</code>. <code>-Scope EntraOnly</code> used to be accepted and silently produce a run that could never gather any data; it now <strong>throws immediately</strong> with a redirect to the tool that actually has an Entra collection path:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invoke-AzureScout collects ARM/Resource Graph data only -- the assessment</span></span>\n<span class="line"><span>platform&#39;s Collect layer has no Entra ID collection path. Use</span></span>\n<span class="line"><span>&#39;Invoke-AzureScout -Scope EntraOnly&#39; for Entra ID inventory instead.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>ArmOnly</code> and <code>All</code> remain accepted and behave identically (both just run the ARM collect) — kept for forward compatibility rather than removed, since <code>Invoke-Collect</code> has no ARM-vs-Entra branch to differentiate them. This differs from <code>Invoke-AzureScout -Scope</code>, which does gate ARM vs. Entra extraction in inventory mode (see <a href="./../guide/usage.html#scope">Usage Guide</a>) — use that cmdlet for Entra ID inventory.</p></div><h3 id="category-override" tabindex="-1"><code>-Category</code> override <a class="header-anchor" href="#category-override" aria-label="Permalink to &quot;`-Category` override&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Assess: Compute&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Category Compute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Storage</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-Category</code> replaces the categories recorded for the run — and, per the note above, this now <strong>does</strong> change what <code>Invoke-Collect</code> actually queries (it runs only the queries tagged for the categories you pass, plus base data). It never changes which <strong>rules</strong> are scored (<code>Compute</code>&#39;s <code>Rules</code> stay <code>waf.reliability</code>/<code>waf.cost</code>/<code>waf.performance</code> no matter what <code>-Category</code> you pass) — so overriding <code>-Category</code> to something narrower than what those rules need can starve them of data (they&#39;ll show <code>Unknown</code>/fail-vacuously instead of a real result). Prefer leaving <code>-Category</code> unset and letting each assessment use its own manifest-declared <code>Collect</code> list, which is kept in sync with what its <code>Rules</code> actually reference.</p><h3 id="outputformat-—-supported-deliverables" tabindex="-1"><code>-OutputFormat</code> — supported deliverables <a class="header-anchor" href="#outputformat-—-supported-deliverables" aria-label="Permalink to &quot;`-OutputFormat` — supported deliverables&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">The React report is the one supported deliverable</p><p>Only <code>React</code>, <code>Json</code> and <code>JsonEvidence</code> are emitted today in inventory-only, assessment-only, and combined runs. <code>PowerBi</code>, <code>Html</code>, <code>Pptx</code>, <code>Excel</code>, <code>Markdown</code>, <code>AsciiDoc</code>, <code>Word</code>, <code>Pdf</code>, <code>EChartsDashboard</code> and <code>GovernanceReport</code> are <strong>on hold</strong> (<strong>AB#6922</strong>) — the renderers still exist and are still tested, but they are being rebuilt to generate <em>from</em> the React report rather than alongside it, so a document and the page it came from can never disagree.</p><p>Held names still bind for script compatibility, but they warn and are skipped. Export to Markdown, JSON, CSV, PDF (print) or a standalone HTML copy <strong>from the React report page itself</strong>. See <a href="./configuration.html#report-tiers">Report tiers</a>.</p></div><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat Json</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat JsonEvidence</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat React</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat React</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JsonEvidence</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>-OutputFormat</code> also accepts an array (<code>-OutputFormat React,Json</code>). <code>React</code> produces a single self-contained <code>report-react.html</code> — a multi-page application in one file (Overview, Inventory &amp; audit, Assessments and a full conformance register per assessment, Diagrams, Data &amp; drift, Remediation plan) with an Executive / Consultant / Data view-depth toggle, a light/dark theme toggle, and Markdown / JSON / CSV / Print / standalone-HTML exports. Its structure is normative — see <a href="./../reference/react-report-section-contract.html">the React report section contract</a>. <code>Word</code>, <code>EChartsDashboard</code> and <code>Pdf</code> were self-contained tiers added in v2.2.0 and are now held — see <a href="./configuration.html#report-tiers">Report tiers</a>. The same <code>-OutputFormat</code> parameter is available on <code>Invoke-ScoutPipeline</code>.</p><h3 id="outputpath" tabindex="-1"><code>-OutputPath</code> <a class="header-anchor" href="#outputpath" aria-label="Permalink to &quot;`-OutputPath`&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputPath </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D:\\Reports\\Scout&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Each run writes into a timestamped subfolder (<code>&lt;OutputPath&gt;/yyyyMMdd_HHmmss/</code>).</p><h2 id="all-46-registry-entries-—-and-what-the-wizard-actually-offers" tabindex="-1">All 46 registry entries — and what the wizard actually offers <a class="header-anchor" href="#all-46-registry-entries-—-and-what-the-wizard-actually-offers" aria-label="Permalink to &quot;All 46 registry entries — and what the wizard actually offers&quot;">​</a></h2><p>The full catalogue — description, <code>Collect</code>/<code>Ingest</code>, CAF areas / WAF pillars, and legacy manifest report-tier metadata, generated from <code>manifests/assessments.psd1</code> — lives in the <strong><a href="./../design/assessment-registry.html">Assessment Registry</a></strong>. Minimum auth per assessment lives in <strong><a href="./assessment-permissions.html">Auth &amp; permissions per scan type</a></strong>.</p><div class="warning custom-block"><p class="custom-block-title">What the 46 registry entries actually are</p><p><code>manifests/assessments.psd1</code> has <strong>46 keys</strong>. They are not 46 unrelated products, and they are no longer mostly views over one roll-up — the AB#6746 restructure turned the per-pillar and per-design-area assessments into real scored entries. They group as:</p><ul><li><strong>11 Cloud Adoption Framework</strong> — one per design area (<code>CAF: Governance</code>, <code>CAF: Security</code>, <code>CAF: Network topology and connectivity</code>, …) plus the <code>CAF: Azure Landing Zone</code> roll-up, which pulls in every CAF and WAF rule file at once.</li><li><strong>9 Well-Architected Framework</strong> — one per pillar (<code>WAF: Reliability</code>, <code>WAF: Security</code>, …), plus <code>WAF: Azure Local</code> and <code>WAF: Maturity Model</code>.</li><li><strong>19 <code>Assess: </code> service-category slices</strong> — a category filter over the shared rule set, one per Scout inventory category. <code>Compute</code> filters what gets <em>collected</em>; <code>Assess: Compute</code> filters what gets <em>scored</em>, which is why they carry the prefix. The old unprefixed name still resolves, with a warning telling you what to change.</li><li><strong>7 specialised and workload</strong> — <code>Workload: AVS</code>, <code>Workload: AVS Landing Zone</code>, <code>Microsoft: CASA</code>, <code>Microsoft: DevOps Capability</code>, <code>Microsoft: FinOps Review</code>, <code>Microsoft: SMART Migration</code> and <code>Assess: Compliance</code>.</li></ul><p>A few legacy sub-bundles still sit inside those groups — <code>Scout: Governance Baseline</code>, <code>Scout: Monitoring Baseline</code> and <code>Scout: Update Manager</code>, each a narrower cut of a broader entry. Two earlier entries are gone: <code>Policy</code> (byte-identical to <code>Scout: Governance Baseline</code>) and <code>Estate</code> (declared no rules, so it scored nothing) were both removed under AB#6795 rather than left to return a misleading &quot;no findings&quot;.</p><h3 id="renamed-in-v3-8-0-—-old-names-keep-working" tabindex="-1">Renamed in v3.8.0 — old names keep working <a class="header-anchor" href="#renamed-in-v3-8-0-—-old-names-keep-working" aria-label="Permalink to &quot;Renamed in v3.8.0 — old names keep working&quot;">​</a></h3><p>Twelve registry keys gained a namespace prefix (<code>CAF:</code> / <code>Microsoft:</code> / <code>Scout:</code> / <code>Workload:</code>) so the menu groups by who owns the checklist. Every old name still resolves — a run using one proceeds against the new entry and prints a warning naming the replacement.</p><table tabindex="0"><thead><tr><th>Old name</th><th>New name</th></tr></thead><tbody><tr><td><code>LandingZone</code></td><td><code>CAF: Azure Landing Zone</code></td></tr><tr><td><code>CASA</code></td><td><code>Microsoft: CASA</code></td></tr><tr><td><code>DevOps Capability Assessment</code></td><td><code>Microsoft: DevOps Capability</code></td></tr><tr><td><code>SMART</code></td><td><code>Microsoft: SMART Migration</code></td></tr><tr><td><code>FinOps Review</code></td><td><code>Microsoft: FinOps Review</code></td></tr><tr><td><code>Cost</code></td><td><code>Scout: Cost Optimization</code></td></tr><tr><td><code>CrossResource</code></td><td><code>Scout: Cross-Resource</code></td></tr><tr><td><code>Monitoring</code></td><td><code>Scout: Monitoring Baseline</code></td></tr><tr><td><code>UpdateManager</code></td><td><code>Scout: Update Manager</code></td></tr><tr><td><code>Governance</code></td><td><code>Scout: Governance Baseline</code></td></tr><tr><td><code>AVS Workload</code></td><td><code>Workload: AVS</code></td></tr><tr><td><code>AVS Landing Zone</code></td><td><code>Workload: AVS Landing Zone</code></td></tr></tbody></table><p><strong>The full list, with the rule files and the automated-versus-manual split behind each, is on one generated page: <a href="./../reference/assessment-catalogue.html">Assessment Catalogue</a>.</strong> Prefer it to any count written in prose here — it is generated from the registry and cannot drift.</p><p><strong>The interactive wizard hides any entry whose rule-file glob matches no file on disk.</strong> An entry that runs and silently returns zero findings reads as &quot;nothing wrong&quot; rather than &quot;nothing was checked&quot;, so it is left off the menu rather than shown. You can still run one directly with <code>-Assessment &lt;Name&gt;</code> — the filter is a menu courtesy, not an authorization check. <code>Microsoft: SMART Migration</code> is gated separately, on whether the estate actually has migration data to score.</p></div><h2 id="scoring" tabindex="-1">Scoring <a class="header-anchor" href="#scoring" aria-label="Permalink to &quot;Scoring&quot;">​</a></h2><ul><li>Each rule evaluates to <strong>Pass</strong>, <strong>Fail</strong>, <strong>Partial</strong>, <strong>Manual</strong>, <strong>Unknown</strong>, or <strong>Error</strong>.</li><li>Framework scores are the rule-count-weighted roll-up of area/pillar scores.</li><li><code>Unknown</code>/<code>Error</code> are surfaced, never silently dropped — a broken rule cannot inflate a score.</li><li>The <strong><code>Manual</code></strong> status intentionally hands the un-automatable checks to a human, with the collected evidence already attached.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Every assessment needs <strong>ARM <code>Reader</code> at the tenant-root management group</strong>. There are no exceptions, and a narrower scope degrades results to an explicit <code>Unknown</code> rather than a false zero.</p><p>The full story — the per-assessment matrix, when Microsoft Graph permissions are actually required, and precisely what <code>-PermissionAudit</code> does and does not verify — lives on one page: <strong><a href="./assessment-permissions.html">Auth &amp; permissions per scan type</a></strong>.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pre-flight before any collection runs</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CAF: Azure Landing Zone&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermissionAudit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">Why this section is short</p><p>This page used to restate the permissions model in full, giving three separate descriptions of it across the documentation — this page, the assessment permissions page, and the inventory <a href="./../guide/permissions.html">Permissions</a> page. They drifted, as three copies of anything do. The detail now lives in one place and the other two link to it.</p></div><h2 id="more-on-assessment" tabindex="-1">More on assessment <a class="header-anchor" href="#more-on-assessment" aria-label="Permalink to &quot;More on assessment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./analysis-features.html">Analysis features</a></td><td>Cross-run drift, cost anomaly detection, IaC gap detection, IoT deep coverage</td></tr><tr><td><a href="./configuration.html">Configuration and report tiers</a></td><td>Saving/loading config, the three live outputs, and held legacy renderers</td></tr><tr><td><a href="./../reference/assessment-catalogue.html">Assessment Catalogue</a></td><td>All 46 assessments, their rule files, and the automated-versus-manual split</td></tr></tbody></table><h2 id="design-reference" tabindex="-1">Design reference <a class="header-anchor" href="#design-reference" aria-label="Permalink to &quot;Design reference&quot;">​</a></h2><p>The full architecture, rule catalogue, and decision records live in the <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/pmo/plans/master-plan.md" target="_blank" rel="noreferrer">Master Design &amp; Plan</a> and the <a href="./../design/assessment-registry.html">assessment registry</a>.</p>',72)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
